def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Improved version of `equation_v2` for better physical correlations."""
    return parameters[0] + parameters[1] * gate_voltage_abs + parameters[2] * drain_voltage_abs + parameters[3] ** (gate_voltage_abs ** 2) * (drain_voltage_abs ** 2) + parameters[4] ** (gate_voltage_abs ** 3) * (drain_voltage_abs ** 3)
